    Returns integers x and y that satisfy ax + by = n as a tuple, or None if no solution exists.

    Args:
        a: coefficient of x
        b: coefficient of y
        n: constant term

    Returns:
        Tuple (x, y) satisfying ax + by = n, or None if no solution exists
    """
    # Handle edge cases
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)

    if a == 0:
        return (None, None) if n % b != 0 else (0, n // b)

    if b == 0:
        return (None, None) if n % a != 0 else (n // a, 0)

    # Use extended Euclidean algorithm to find gcd and coefficients
    def extended_gcd(x, y):
