        x2 = y1 - (y // x) * x1
        y2 = x1
        return gcd, x2, y2

    gcd, x0, y0 = extended_gcd(a, b)

    # Check if solution exists
    if n % gcd != 0:
        return None

    # Scale the solution
    x = x0 * (n // gcd)
    y = y0 * (n // gcd)

    return (x, y)
