def is_undulating(n):
    """
    Check whether the given number is undulating or not.

    An undulating number is a number where digits alternate between two different digits.
    For example, 1212121 is undulating because it alternates between 1 and 2.

    Args:
        n (int): The number to check

    Returns:
        bool: True if the number is undulating, False otherwise
    """
    # Convert number to string to work with digits
    s = str(n)

    # Numbers with less than 3 digits cannot be undulating
    if len(s) < 3:
        return False

    # Check if the first two digits are different
    if s[0] == s[1]:
        return False

    # Check if all digits follow the alternating pattern
    for i in range(2, len(s)):
        if s[i] == s[i-1]:
            return False

    # For undulating numbers, digits should alternate between two values
    # Check if the pattern alternates correctly
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            return False

    # Check if the pattern is consistent (alternating between two digits)
    first_digit = s[0]
    second_digit = s[1]

    for i in range(2, len(s)):
        if s[i] != first_digit and s[i] != second_digit:
            return False
        if i % 2 == 0:
            if s[i] != first_digit:
                return False
        else:
            if s[i] != second_digit:
                return False

    return True
